#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int count = 0;
    for (int i = 0; i + 1 < static_cast<int>(s.size()); ++i) {
        count += (s[i] == 'V' && s[i + 1] == 'K');
    }

    int answer = count;
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        int before = 0, after = 0;

        if (i > 0)
            before += (s[i - 1] == 'V' && s[i] == 'K');
        if (i + 1 < static_cast<int>(s.size()))
            before += (s[i] == 'V' && s[i + 1] == 'K');

        s[i] = (s[i] == 'V' ? 'K' : 'V');

        if (i > 0)
            after += (s[i - 1] == 'V' && s[i] == 'K');
        if (i + 1 < static_cast<int>(s.size()))
            after += (s[i] == 'V' && s[i + 1] == 'K');

        answer = max(answer, count - before + after);
        s[i] = (s[i] == 'V' ? 'K' : 'V');
    }

    cout << answer;
    return 0;
}

